import heapq

def match(orders):
    trades = []
    orders_info = {}  # id -> dict(side, price, qty(remaining), active, arrival)
    buy_heap = []   # (-price, arrival, id)
    sell_heap = []  # (price, arrival, id)
    arrival_counter = 0

    def add_to_book(order_id):
        info = orders_info[order_id]
        if info['side'] == 'buy':
            heapq.heappush(buy_heap, (-info['price'], info['arrival'], order_id))
        else:
            heapq.heappush(sell_heap, (info['price'], info['arrival'], order_id))

    def top_valid(heap):
        while heap:
            item = heap[0]
            oid = item[2]
            info = orders_info.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(heap)
                continue
            return oid
        return None

    def match_incoming(incoming_id, side, price, qty, order_type):
        opposite_heap = sell_heap if side == 'buy' else buy_heap

        while qty > 0:
            oid = top_valid(opposite_heap)
            if oid is None:
                break
            resting = orders_info[oid]
            resting_price = resting['price']

            if order_type != 'market':
                if side == 'buy':
                    if resting_price > price:
                        break
                else:
                    if resting_price < price:
                        break

            trade_qty = min(qty, resting['qty'])
            trade_price = resting_price

            if side == 'buy':
                buy_id = incoming_id
                sell_id = oid
            else:
                buy_id = oid
                sell_id = incoming_id

            trades.append([buy_id, sell_id, trade_price, trade_qty])

            resting['qty'] -= trade_qty
            qty -= trade_qty

            if resting['qty'] <= 0:
                resting['active'] = False
                heapq.heappop(opposite_heap)

        return qty

    for order in orders:
        op = order[0]
        if op == 'cancel':
            _, oid = order
            info = orders_info.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if op == 'limit':
            _, oid, side, price, qty = order
        elif op == 'ioc':
            _, oid, side, price, qty = order
        elif op == 'market':
            _, oid, side, qty = order
            price = None
        else:
            continue

        orders_info[oid] = {
            'side': side,
            'price': price,
            'qty': qty,
            'active': True,
            'arrival': arrival_counter
        }
        arrival_counter += 1

        remaining = match_incoming(oid, side, price, qty, op)

        orders_info[oid]['qty'] = remaining

        if op == 'limit' and remaining > 0:
            add_to_book(oid)
        else:
            orders_info[oid]['active'] = False

    return trades

